379	// ─── Step Handlers Registry ───
380	// Modules register custom goal step handlers. Engine handles universal primitives
381	// (move_to, interact, announce, wait). Everything else → registry.
382	
383	export type InteractionRunner = (initiator: Agent, target: Agent, purpose: string, importance: number) => Promise<{ ownerLine: string; targetLine: string }>;
384	
385	export interface StepExecutionContext {
386	  goal: NpcGoal;
387	  step: GoalStep;
388	  ownerId: string;
389	  owner: Agent;
390	  agents: Map<string, Agent>;
391	  locations: LocationGraph;
392	  runInteraction: InteractionRunner;
393	  onCrimeEvent?: (event: { type: string; subject: string; object?: string; location: string; importance: number; payload: Record<string, unknown> }) => Promise<void>;
394	  crimeScenes?: Map<string, CrimeScene[]>;
395	  evidenceLayer?: EvidenceLayer;
396	  /** GoalManager for clearing goals (arrest → clear target goals, flee → clear own goals) */
397	  goalManager: GoalManager;
398	  /** Add a mood modifier to an NPC (SPEC-mood-modifiers) */
399	  addMoodModifier: MoodModifierCallback;
400	}
401	
402	export type StepHandlerFn = (ctx: StepExecutionContext) => Promise<GoalActionResult | null>;
403	
404	const STEP_HANDLERS: Map<string, StepHandlerFn> = new Map();
405	
406	export function registerStepHandler(action: string, handler: StepHandlerFn): void {
407	  if (!action) throw new Error(`[StepHandler] Empty action name`);
408	  if (typeof handler !== 'function') throw new Error(`[StepHandler] Handler for '${action}' is not a function`);
409	  STEP_HANDLERS.set(action, handler);
410	}
411	
412	export function getStepHandler(action: string): StepHandlerFn | null {
413	  return STEP_HANDLERS.get(action) ?? null;
414	}
