1	/**
2	 * World Editor — local server for viewing and editing CLWA world data.
3	 *
4	 * - Serves web UI from public/
5	 * - Reads/writes JSON files in the world directory
6	 * - Supports any world via --world= argument
7	 *
8	 * Usage: bun run tools/world-editor/server.ts [--world=path/to/world]
9	 * Default: worlds/millhaven
10	 * Open: http://localhost:3001
11	 */
12	
13	import { resolve, join, basename } from "path";
14	import { readdir } from "fs/promises";
15	import { getAllRegisteredEventTypes, getEventTypesByCategory, getAllRegisteredSources, BELIEF_SOURCE } from "@clwa/engine";
16	import { registerCrimeJusticeModule, registerSocialModule } from "@clwa/modules";
17	
18	// Populate engine registries so we can serve valid options to the editor UI
19	registerSocialModule();
20	registerCrimeJusticeModule();
21	
22	// ─── Configuration ───
23	
24	const worldArg = process.argv.find(a => a.startsWith('--world='))?.split('=')[1];
25	const WORLD_DIR = resolve(
26	  worldArg ?? join(import.meta.dir, "../../worlds/millhaven")
27	);
28	const WORLD_NAME = basename(WORLD_DIR);
29	const PUBLIC_DIR = resolve(import.meta.dir, "public");
30	const PORT = 3001;
31	
32	// ─── Helpers ───
33	
34	async function readJSON(path: string) {
35	  const file = Bun.file(path);
36	  return file.json();
37	}
38	
39	async function writeJSON(path: string, data: unknown) {
40	  await Bun.write(path, JSON.stringify(data, null, 2) + "\n");
41	}
42	
43	// ─── API handlers ───
44	
45	async function handleAPI(req: Request, pathname: string): Promise<Response> {
46	  const method = req.method;
47	  const cors = { 'Access-Control-Allow-Origin': '*' };
48	
49	  // GET /api/meta — world metadata for UI
50	  if (pathname === "/api/meta" && method === "GET") {
51	    return Response.json({ worldName: WORLD_NAME, worldDir: WORLD_DIR }, { headers: cors });
52	  }
53	
54	  // GET /api/registry — registered engine types for typed dropdowns
55	  if (pathname === "/api/registry" && method === "GET") {
56	    const npcsDir = join(WORLD_DIR, "npcs");
57	    const files = await readdir(npcsDir);
58	    const npcIds = files.filter(f => f.endsWith(".json")).map(f => f.replace(".json", ""));
59	    // Collect relationship types from world data
60	    const rels = await readJSON(join(WORLD_DIR, "relationships.json")) as Array<{ type?: string }>;
61	    const relTypes = [...new Set(rels.map(r => r.type).filter(Boolean))].sort();
62	    // Collect roles from NPC data
63	    const npcData = await Promise.all(
64	      files.filter(f => f.endsWith(".json")).map(f => readJSON(join(npcsDir, f)))
65	    ) as Array<{ role?: string }>;
66	    const roles = [...new Set(npcData.map(n => n.role).filter(Boolean))].sort();
67	    return Response.json({
68	      eventTypes: getAllRegisteredEventTypes(),
69	      motiveTypes: getEventTypesByCategory('motive'),
70	      sources: [...getAllRegisteredSources(), ...Object.values(BELIEF_SOURCE)].filter((v, i, a) => a.indexOf(v) === i),
71	      npcIds,
72	      relationshipTypes: [...new Set([...relTypes, 'friend', 'colleague', 'acquaintance', 'rival', 'enemy'])].sort(),
73	      roles,
74	    }, { headers: cors });
75	  }
76	
