324	export function checkRequirements(
325	  aff: AffordanceDefinition,
326	  npcId: string,
327	  agent: Agent,
328	  ctx: AffordanceContext,
329	): AffordanceTarget | null {
330	  const req = aff.requires;
331	
332	  if (req.notGuard && agent.profile.investigator) return null;
333	  if (req.isGuard && !agent.profile.investigator) return null;
334	  if (req.isInvestigator && !agent.profile.investigator) return null;
335	  if (req.canSentence && !agent.profile.canSentence) return null;
336	  if (req.period && !req.period.includes(ctx.period)) return null;
337	  if (req.moodBelow !== undefined && agent.state.mood >= req.moodBelow) return null;
338	  if (aff.suppressNearPlayer && ctx.playerLocation === agent.state.location) return null;
339	
340	  // Module-provided requirement checks — generic iteration over registry
341	  if (!checkRegistryRequirements(req, agent, ctx)) return null;
342	
343	  const target = findTarget(aff, npcId, agent, ctx);
344	  if (!target) return null;
345	
346	  if (!checkPostTargetRequirements(req, npcId, target, ctx)) return null;
347	
348	  return target;
349	}
